CREATE TABLE IF NOT EXISTS rollup (day TEXT PRIMARY KEY, data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS bots (hour TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (hour, kind, name)); ALTER TABLE riders ADD COLUMN last INTEGER; UPDATE riders SET last = (SELECT MAX(ts) FROM events WHERE events.ih = riders.ih); UPDATE riders SET last = first WHERE last IS NULL; CREATE INDEX IF NOT EXISTS riders_last ON riders(last);
